const shuffle=x=>{const y=[...x];for(let i=y.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[y[i],y[j]]=[y[j],y[i]];}return y};
const localKey='islama-v4-puntuazioak';
function getScores(){try{return JSON.parse(localStorage.getItem(localKey))||{};}catch{return {}}}
function saveScore(game,name,score){let a=getScores();a[game]||={};let id=name.toLocaleLowerCase('eu');if(!a[game][id]||a[game][id].score<score)a[game][id]={name,score,timestamp:Date.now()};try{localStorage.setItem(localKey,JSON.stringify(a))}catch{}}
function leaders(game){let a=getScores()[game]||{};return Object.values(a).sort((u,v)=>v.score-u.score||u.timestamp-v.timestamp).slice(0,10)}
async function ranking(){const g=$game(state.game);$('rank-game-title').textContent=g?.name||'Sailkapena';let rows=leaders(state.game);if(state.online&&state.game){try{let res=await fetch('/api/leaderboard?game='+encodeURIComponent(state.game),{cache:'no-store'});if(!res.ok)throw new Error('Sailkapena');rows=(await res.json()).entries||[];}catch{$('ranking-rows').innerHTML='<p class="rank-empty">Sailkapena ezin da kargatu.</p>';return}}$('ranking-rows').innerHTML=rows.length?rows.map((r,i)=>`<div class="rank-row"><span class="rank-number">${['🥇','🥈','🥉'][i]||i+1+'.'}</span><span class="rank-name">${esc(r.name)}</span><span class="rank-score">${r.score.toLocaleString('eu-ES')}</span></div>`).join(''):'<p class="rank-empty">Oraindik ez dago errekorrik.<br>Izan zaitez lehena!</p>';}
function gameScore(){if(state.finished&&state.serverScore!==null)return state.serverScore;let total=totalQuestions();let ratio=total?state.correct/total:0;let elapsed=Math.min(180,180-state.seconds);let points=Math.round(750*ratio+250*ratio*(1-elapsed/180));if(state.game==='merkataritza')points-=70*state.errors;return Math.max(0,Math.min(1000,points))}
function totalQuestions(){let g=$game(state.game);return ['sceneQuiz','imageQuiz'].includes(g.kind)?state.questions.length:MATCH_DATA[state.game].items.length}
function gamePairs(){let data=MATCH_DATA[state.game],c={};if(state.game==='merkataritza')return data.correct;if(state.game==='denbora')return {t1:'570',t2:'610',t3:'622',t4:'630',t5:'632'};data.targets.forEach((a)=>{c[a[0]]=a[0]});return c}
