async function startGame(){quizEpoch++;if(quizDelay!==null){clearTimeout(quizDelay);quizDelay=null;}quizBusy=false;let nick=$('player-name').value.trim().normalize('NFC');if(!/^[\p{L}\p{N}_ -]{2,18}$/u.test(nick)){$('modal-error').textContent='Idatzi 2 eta 18 karaktere arteko goitizen bat.';return}let serverSession=null;if(state.online){const pin=$('player-pin').value.trim();if(!/^\d{6,10}$/.test(pin)){$('modal-error').textContent='Idatzi 6–10 zenbakiko PIN bat.';return}try{let response=await fetch('/api/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({gameId:state.game,nickname:nick,pin})});let data=await response.json();if(!response.ok)throw new Error(data.error||'Errorea');serverSession=data;}catch(e){$('modal-error').textContent=e.message;return}}state.session=serverSession?.sessionId||null;state.nickname=nick;closeStart();$('result-modal').classList.add('hidden');stopClock();state.correct=0;state.errors=0;state.lives=3;state.step=0;state.seconds=180;state.started=Date.now();state.assignments={};state.chosen=null;state.history=[];state.finished=false;state.questions=[];state.answerLog=[];state.serverScore=null;quizBusy=false;state.trayOrder=null;state.placementLocked=[];const id=state.game;let base=id==='mezkitako_atalak'?MOSQUE_QUESTIONS:id==='artea'?ART_QUIZ:CHOICE_DATA[id]||[];if(serverSession?.questionOrder)state.questions=serverSession.questionOrder.map(i=>base[i]);else if(id==='mezkitako_atalak')state.questions=[...shuffle(base.slice(0,6)),...shuffle(base.slice(6))];else if(id==='artea'||id==='hiria')state.questions=shuffle(base);else state.questions=base;$('home-screen').classList.add('hidden');$('game-screen').classList.remove('hidden');$('hud-title').textContent=$game(id).number+'. '+$game(id).name;$('game-instruction').textContent=({arabia:'Aurkitu lekuak mapan eta erantzun galderei.',denbora:'Jarri gertakariak denbora-lerroan, zaharrenetik berrienera.',bost:'Lotu islamaren bost zutabeak beren definizioekin.',hedapena:'Begiratu mapari eta erantzun hedapenari buruzko galderei.',kalifaldi:'Lotu hiru kalifaldiak beren urte, hiriburu eta familiekin.',gizartea:'Kokatu talde sozialak piramidearen maila egokietan.',hiria:'Bilatu hiri musulmanaren osagaiak irudian.',merkataritza:'Sailkatu produktuak eta jarduerak dagokien multzoan.',artea:'Aztertu irudiak eta ezagutu ondare artistikoa.',mezkita:'Ezagutu mezkitako atalak eta egin klik dagokien tokian.'})[id];$('quest-source').textContent='PDF · '+$game(id).pages+' orrialdeak';$('feedback').textContent='Prest? Aukeratu erantzuna.';$('feedback').className='feedback';$('check-button').classList.add('hidden');$('card-tray').classList.add('hidden');$('reset-button').classList.add('hidden');renderGame();updateHUD();ranking();state.clock=setInterval(()=>{if(state.finished)return;state.seconds--;updateHUD();if(state.seconds<=0)endGame();},1000);window.scrollTo({top:0,behavior:'instant'})}
