const sceneImg=({arabia:'arabia-art.webp',hedapena:'pdf-16.webp',hiria:'pdf-21.webp',mezkitako_atalak:'mezkita-escena-erreferentzia.webp'})[g];const spots=g==='arabia'?ARABIA_SPOTS:g==='hiria'?CITY_SPOTS:g==='mezkitako_atalak'?MOSQUE_PARTS:[];let isHot=q.mode==='spot';const markers=isHot?spots.map((p,i)=>`<button class="scene-hotspot" style="left:${p.x}%;top:${p.y}%" data-spot="${p.id}" aria-label="${g==='mezkitako_atalak'?`${i+1}. kokapena`:esc(p.label)}"><span>${g==='mezkitako_atalak'?i+1:esc(p.label)}</span></button>`).join(''):'';
