function answerQuestion(answer,el){if(state.finished||quizBusy)return;quizBusy=true;state.answerLog.push(answer);const q=currentTask(),ok=answer===q.answer;if(ok){state.correct++;$('feedback').textContent='Bikain! Erantzun zuzena!';$('feedback').className='feedback good';}else{state.errors++;state.lives=Math.max(0,state.lives-1);$('feedback').textContent='Ez da zuzena. Hurrengo erronka!';$('feedback').className='feedback bad';}if(state.game==='mezkitako_atalak'){const part=MOSQUE_PARTS.find(p=>p.id===q.answer);if(part){$('feedback').textContent+=' · '+part.label+': '+part.hint;const illustration=$('quest-illustration');illustration.innerHTML=`<img src="${ASSET(part.image)}" alt="${esc(part.label)}">`;}}state.history.push(ok);if(el)el.classList.add(ok?'correct':'wrong');document.querySelectorAll('#play-scene [data-spot],#play-scene [data-answer]').forEach(b=>b.disabled=true);updateHUD();soundBeep(ok);const epoch=quizEpoch;quizDelay=setTimeout(()=>{if(epoch!==quizEpoch)return;quizDelay=null;quizBusy=false;if(state.finished)return;state.step++;if(state.lives===0||state.step>=state.questions.length){endGame();return}renderQuiz()},state.game==='mezkitako_atalak'?1750:700)}
function getSelectedText(id){return MATCH_DATA[state.game].items.find(i=>i[0]===id)?.[1]||''}
function renderPlacement(){let g=state.game,data=MATCH_DATA[g];$('play-scene').classList.remove('mosque-mode');$('reset-button').classList.remove('hidden');$('check-button').classList.remove('hidden');$('card-tray').classList.remove('hidden');$('card-tray').classList.remove('glossary');setQuest('Osatu irudia!', 'Aukeratu txartela eta egin klik hutsik dagoen tokian.',null,Math.min(data.items.length,Object.values(state.assignments).flat().length+1),data.items.length);$('level-badge').textContent='1. MAILA';let scene=$('play-scene');if(g==='bost'){scene.innerHTML=`<div class="pillars-stage"><h3 class="placement-heading">Islamaren bost zutabeak</h3><div class="pillar-columns">${data.targets.map(t=>`<div class="pillar-column"><img src="${ASSET(t[0]+'.webp')}" alt="${esc(t[1])}"><strong>${esc(t[1])}</strong>${drop(t[0],'Jarri definizioa hemen')}</div>`).join('')}</div></div>`}else if(g==='gizartea'){scene.innerHTML=`<div class="pyramid-layout"><div class="pyramid-help"><p>1. Aristokrazia</p><p>2. Klase ertainak<br><small>(PDF: «Herriaren masan»)</small></p><p>3. Esklaboak</p></div><div class="pyramid">${[['arist','arist-desc'],['herria','herria-desc'],['eskl','eskl-desc']].map(t=>`<div class="pyramid-level">${drop(t[0],'Taldea')}${drop(t[1],'Ezaugarriak')}</div>`).join('')}<span class="pyramid-caption">Gizarte-egitura · PDFko 20. orrialdea</span></div></div>`}else if(g==='denbora'){scene.innerHTML=`<div class="timeline-scene"><h3 class="placement-heading">Mahomaren bizitza · 570–632</h3><div class="drop-row">${data.targets.map(t=>drop(t[0],'Gertaera '+t[0].replace('t',''))).join('')}</div><div class="timeline-road"></div><p class="scene-info">Ordenatu bost gertaerak zaharrenetik berrienera.</p></div>`}else if(g==='kalifaldi'){const cols=[['ort','Kalifaldi ortodoxoa','pdf-14.webp'],['ome','Omeiatar kalifaldia','pdf-15.webp'],['abb','Abbastar kalifaldia','pdf-13.webp']];scene.innerHTML=`<div class="columns-califates">${cols.map(t=>`<div class="caliphate-col"><h3>${t[1]}</h3><img src="${ASSET(t[2])}" alt="${t[1]}">${data.targets.filter(a=>a[0].startsWith(t[0])).map(v=>drop(v[0],v[1])).join('')}</div>`).join('')}</div>`}else if(g==='merkataritza'){scene.innerHTML=`<div class="category-scene">${[['nek','Nekazaritza','farmer-art.webp'],['esku','Eskulangintza','pdf-24.webp'],['merk','Merkataritza','market-art.webp']].map(a=>`<div class="category-col"><h3>${a[1]}</h3><img src="${ASSET(a[2])}" alt="${a[1]}">${drop(a[0],'Hemen kokatu',true)}</div>`).join('')}</div>`}
updateTray();bindDrops();updateHUD();}
function drop(id,label,isCategory=false){
 const v=state.assignments[id];
 if(isCategory){
  const cards=Array.isArray(v)?v:[];
  return `<div class="category-drop-wrap"><button type="button" class="drop-slot" data-drop="${id}" data-category="yes" aria-label="${esc(label)}: aukeratutako txartela gehitu"><span class="slot-name">${esc(label)}</span><span class="assigned-text">${cards.length} txartel · + Gehitu</span></button><div class="category-items" aria-label="Kokatutako txartelak">${cards.map(card=>`<button type="button" class="category-unassign ${state.placementLocked?.includes(card)?'verified':''}" data-unassign="${card}" data-from="${id}" ${state.placementLocked?.includes(card)?'disabled':''} aria-label="${esc(getSelectedText(card))} ${state.placementLocked?.includes(card)?'egiaztatuta':'kendu'}" title="${state.placementLocked?.includes(card)?'Erantzun zuzena':'Kendu eta beste kategoria batean kokatu'}">${esc(getSelectedText(card))} <span aria-hidden="true">${state.placementLocked?.includes(card)?'✓':'×'}</span></button>`).join('')}</div></div>`;
 }
 const text=v?`<span class="assigned-text">${esc(getSelectedText(v))}</span>`:'<span class="assigned-text">+ Hautatu txartela</span>';
 return `<button type="button" class="drop-slot" data-drop="${id}" data-category="no" aria-label="${esc(label)}"><span class="slot-name">${esc(label)}</span>${text}</button>`;
}
function updateTray(){let d=MATCH_DATA[state.game],assigned=Object.values(state.assignments).flat();let ordered=shuffle(d.items).map(a=>a[0]);if(!state.trayOrder||state.trayOrderGame!==state.game){state.trayOrder=ordered;state.trayOrderGame=state.game;}$('card-tray').innerHTML=`<div class="tray-heading">Aukeratu txartel bat eta jarri dagokion lekuan · Arrastatu ere egin dezakezu</div>${state.trayOrder.map(id=>{let item=d.items.find(x=>x[0]===id),placed=assigned.includes(id);return `<button class="pick-card ${state.chosen===id?'chosen':''} ${placed?'placed':''}" data-pick="${id}" draggable="${!placed}" ${placed?'disabled':''}>${esc(item[1])}</button>`}).join('')}`;$('card-tray').querySelectorAll('[data-pick]').forEach(b=>{b.addEventListener('click',()=>{if(b.disabled)return;state.chosen=b.dataset.pick;updateTray()});b.addEventListener('dragstart',e=>{state.chosen=b.dataset.pick;e.dataTransfer.setData('text/plain',b.dataset.pick);e.dataTransfer.effectAllowed='move'})});}
function bindDrops(){
 $('play-scene').querySelectorAll('[data-drop]').forEach(b=>{b.addEventListener('click',()=>putCard(b.dataset.drop));b.addEventListener('dragover',e=>{e.preventDefault();b.classList.add('drag-over')});b.addEventListener('dragleave',()=>b.classList.remove('drag-over'));b.addEventListener('drop',e=>{e.preventDefault();b.classList.remove('drag-over');state.chosen=e.dataTransfer.getData('text/plain')||state.chosen;putCard(b.dataset.drop)})});
 $('play-scene').querySelectorAll('[data-unassign]').forEach(b=>b.addEventListener('click',()=>{
  const cat=b.dataset.from,id=b.dataset.unassign;
  if(!Array.isArray(state.assignments[cat])||state.placementLocked?.includes(id))return;
  state.assignments[cat]=state.assignments[cat].filter(x=>x!==id);
  state.chosen=null;state.step=Object.values(state.assignments).flat().length;
  renderPlacement();$('feedback').textContent='Txartela kendu duzu. Beste kategoria batean jar dezakezu.';$('feedback').className='feedback';
 }));
}
function putCard(slot){if(state.finished||state.lives<=0)return;if(state.placementLocked?.includes(state.chosen))return;if(!state.chosen){$('feedback').textContent='Lehenik, aukeratu beheko txartel bat.';return}let card=state.chosen;let category=state.game==='merkataritza';for(const [k,v] of Object.entries(state.assignments)){if(Array.isArray(v))state.assignments[k]=v.filter(x=>x!==card);else if(v===card)delete state.assignments[k]}if(category){state.assignments[slot]??=[];state.assignments[slot].push(card)}else state.assignments[slot]=card;state.chosen=null;$('feedback').textContent='Jarrita! Jarraitu beste txartelekin.';$('feedback').className='feedback';state.step=Object.values(state.assignments).flat().length;renderPlacement();}
function submitPlacement(){
 if(state.finished||state.lives<=0)return;
 const d=MATCH_DATA[state.game],answers=gamePairs(),locked=new Set(state.placementLocked||[]);
 const placed=Object.values(state.assignments).flat().length,itemsCount=d.items.length;
 let fresh=0,wrong=0;
 // Each click on Egiaztatu is one attempt: right answers are retained and
 // all incorrect cards become available for another try.
 if(placed<itemsCount){$('feedback').textContent='Osatu txartel guztiak egiaztatu aurretik ('+placed+'/'+itemsCount+'). Ez duzu bizitzarik galdu.';$('feedback').className='feedback';return;}
 for(const [slot,cards] of Object.entries(state.assignments)){
  if(!Array.isArray(cards))continue;
  const keep=[];
  for(const card of cards){
   if(locked.has(card)){keep.push(card);continue;}
   if(answers[card]===slot){locked.add(card);keep.push(card);fresh++;}
   else wrong++;
  }
  state.assignments[slot]=keep;
 }
 state.placementLocked=[...locked];state.correct=locked.size;
 state.step=locked.size;state.history=d.items.map(x=>locked.has(x[0]));
 if(wrong){state.errors++;state.lives=Math.max(0,state.lives-1);renderPlacement();$('feedback').textContent=fresh+' zuzen; '+wrong+' berriro kokatzeko. Bizitza bat galdu duzu.';$('feedback').className='feedback bad';if(!state.lives)endGame();return;}
 state.step=itemsCount;renderPlacement();$('feedback').textContent='Bikain! Sailkapen guztiak osatu dituzu.';$('feedback').className='feedback good';endGame();
}
async function endGame(){if(state.finished)return;if(v32SecondContext&&state.game==='mezkitako_atalak'){const callback=v32SecondContext;const result={score:gameScore(),correct:state.correct,total:totalQuestions(),errors:state.errors,seconds:state.seconds,history:[...state.history],completed:state.step>=state.questions.length&&state.questions.length===12&&state.seconds>0&&state.lives>0};v32SecondContext=null;state.online=v32OnlineBefore;state.finished=true;stopClock();viewHome();callback.onFinish(result);return;}state.finished=true;stopClock();let score=gameScore(),improved=false;if(state.online){try{const g=$game(state.game);const answers=['sceneQuiz','imageQuiz'].includes(g.kind)?state.answerLog:state.assignments;let response=await fetch('/api/finish',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({sessionId:state.session,gameId:state.game,answers})});let result=await response.json();if(!response.ok)throw new Error(result.error||'Ezin izan da puntuazioa gorde.');score=result.score;state.correct=result.correctCount;state.serverScore=score;improved=true;}catch(e){$('feedback').className='feedback bad';$('feedback').textContent=e.message+' · Puntuazioa ez da online gorde.';state.finished=false;return}}else{const complete=state.game!=='merkataritza'||state.correct===totalQuestions();if(complete){let old=leaders(state.game).find(x=>x.name.toLowerCase()===state.nickname.toLowerCase());improved=!old||score>old.score;saveScore(state.game,state.nickname,score);}state.serverScore=score;}$('result-title').textContent=state.correct===totalQuestions()?'Zorionak!':'Partida amaitu da!';$('result-score').textContent=score.toLocaleString('eu-ES')+' puntu';$('result-detail').textContent=`${state.correct}/${totalQuestions()} asmatuta · ${180-state.seconds} segundo · ${state.errors} huts.`;$('result-ranking-note').textContent=state.game==='merkataritza'&&state.correct<totalQuestions()?'Partida amaitu gabe: emaitza ez da errekorretan gorde.':state.online?'Zure puntuazioa online egiaztatu eta gorde da.':improved?'Zure errekor berria gorde da!':'Zure errekorra mantendu da.';$('result-modal').classList.remove('hidden');ranking();soundBeep(true)}

function soundBeep(ok){if(!state.sound)return;try{let c=new(window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator(),v=c.createGain();o.type='sine';o.frequency.value=ok?690:240;v.gain.value=.035;o.connect(v).connect(c.destination);o.start();o.stop(c.currentTime+.11);setTimeout(()=>c.close(),400)}catch{}}
/* V36.5 · Clasificación general por las mejores marcas de los diez juegos.
   Es local al navegador: no crea un servidor ni altera los TOP 10 individuales. */
let rankActiveView='overall',rankShowEveryone=false,rankSelectedPlayerKey=null;
const RANK_VALID_GAMES=new Set(GAME_LIST.map(g=>g.id));
const rankKeyName=name=>String(name||'').normalize('NFC').trim().toLocaleLowerCase('eu');
const rankFmt=n=>Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g,'.');
function generalLeaderboard(){
 const raw=getScores();
 const perPlayer=new Map();
 const add=(game,record,fallbackName)=>{
  if(!RANK_VALID_GAMES.has(game)||!record||typeof record!=='object')return;
  // Historical game 7 data from an older version is not a V21 victory.
  if(game==='hiria'&&record.version!=null&&record.version!==21)return;
  const name=String(record.name||record.nick||fallbackName||'').normalize('NFC').trim();
  const numeric=Number(record.score);
  if(!name||!Number.isFinite(numeric)||numeric<0||numeric>1000)return;
  const key=rankKeyName(name);
  let row=perPlayer.get(key);
  if(!row){row={key,name,scores:Object.fromEntries(GAME_LIST.map(g=>[g.id,null]))};perPlayer.set(key,row)}
  if(row.scores[game]===null||numeric>row.scores[game]){
   row.scores[game]=numeric;
   if(row.name===key||numeric>0)row.name=name;
  }
 };
 for(const game of GAME_LIST){
  const records=raw[game.id];
  if(records&&typeof records==='object'&&!Array.isArray(records)){
   for(const [nick,record] of Object.entries(records))add(game.id,record,nick);
  }
 }
 // Read-only support for old versions already stored in this browser.
 const historicExpansion=raw['hedapena-v12'];
 if(historicExpansion&&typeof historicExpansion==='object'&&!Array.isArray(historicExpansion)){
  for(const [nick,record] of Object.entries(historicExpansion))add('hedapena',record,nick);
 }
 try{
  const oldSocial=JSON.parse(localStorage.getItem('islamaren_abentura_v17_gizartea_top10')||'[]');
  if(Array.isArray(oldSocial))for(const record of oldSocial)add('gizartea',record,record?.nick);
 }catch{}
 return [...perPlayer.values()].map(row=>{
  const complete=GAME_LIST.reduce((n,g)=>n+(row.scores[g.id]!==null?1:0),0);
  const total=GAME_LIST.reduce((n,g)=>n+(row.scores[g.id]||0),0);
  return {...row,complete,total};
 }).sort((a,b)=>b.total-a.total||b.complete-a.complete||a.name.localeCompare(b.name,'eu'));
}
/* V36.7 — Sólo presentación: usa generalLeaderboard() de V36.5, sin tocar los cálculos. */
const rankPercent=value=>Math.max(0,Math.min(100,Math.round((Number(value)||0)/100)));
const rankGamePercent=value=>Math.max(0,Math.min(100,Math.round((Number(value)||0)/10)));
function rankMedal(pos){return ['🥇','🥈','🥉'][pos]||String(pos+1).padStart(2,'0')}
function rankAvatar(name){
 const parts=String(name||'').trim().split(/\s+/);
 return esc(parts.slice(0,2).map(p=>[...p][0]||'').join('').toLocaleUpperCase('eu')||'★');
}
function rankingPodium(data){
 const positions=[1,0,2];
 return `<section class="gr-podium" aria-label="Sailkapeneko hiru lehen postuak">
  <div class="gr-podium-head"><span class="gr-podium-heading">✧ OHOREZKO PODIOA ✧</span><span class="gr-podium-hint">Egin klik jokalari batean bere puntuazioak ikusteko</span></div>
  <div class="gr-podium-stage">${positions.map(pos=>{
   const player=data[pos];
   const rank=pos+1;
   return `<div class="gr-podium-slot gr-podium-rank-${rank}">${player?
    `<button class="gr-podium-person" type="button" data-rank-player="${esc(player.key)}" aria-label="${rank}. postua: ${esc(player.name)}, ${rankFmt(player.total)} puntu; emaitzak ikusi">
      <span class="gr-podium-medal" aria-hidden="true">${rankMedal(pos)}</span>
      <span class="gr-podium-avatar" aria-hidden="true">${rankAvatar(player.name)}</span>
      <span class="gr-podium-name">${esc(player.name)}</span>
      <span class="gr-podium-score">${rankFmt(player.total)} <small>puntu</small></span>
      <span class="gr-podium-progress"><span class="gr-podium-progress-fill" style="width:${rankPercent(player.total)}%"></span></span>
      <span class="gr-podium-completed">${player.complete}/10 joko</span>
    </button>`:
    `<div class="gr-podium-vacant"><span class="gr-podium-medal" aria-hidden="true">${rankMedal(pos)}</span><span class="gr-vacant-icon" aria-hidden="true">✦</span><span class="gr-vacant-label">Zure lekua?</span></div>`}
    <div class="gr-podium-plinth" aria-hidden="true"><span>${rank}</span></div>
   </div>`;
  }).join('')}</div>
 </section>`;
}
function rankingPlayerDetail(player){
 return `<section class="gr-selected-player" tabindex="-1" aria-label="${esc(player.name)}: hamar jokoetako puntuazioen xehetasunak">
   <header class="gr-detail-head"><div><span class="gr-detail-kicker">JOKALARIAREN FITXA</span><h3>✦ ${esc(player.name)}</h3><p>${player.complete}/10 joko · ${rankFmt(player.total)} / 10.000 puntu</p></div><button type="button" data-rank-clear="1" aria-label="Xehetasunak itxi">✕ Itxi</button></header>
   <div class="gr-detail-games">${GAME_LIST.map((g,i)=>{
    const score=player.scores[g.id];
    return `<div class="gr-detail-game ${score===null?'gr-detail-pending':''}">
     <div class="gr-detail-game-top"><span class="gr-detail-number">${i+1}</span><span class="gr-detail-game-name">${esc(g.name)}</span><strong>${score===null?'—':rankFmt(score)}<small> / 1.000</small></strong></div>
     <div class="gr-detail-track" role="progressbar" aria-label="${esc(g.name)}: ${score===null?'jokatu gabe':rankFmt(score)+' puntu'}" aria-valuemin="0" aria-valuemax="1000" aria-valuenow="${score===null?0:score}"><span style="width:${rankGamePercent(score)}%"></span></div>
    </div>`;
   }).join('')}</div>
  </section>`;
}
function overallRankingMarkup(){
 const data=generalLeaderboard(),limited=rankShowEveryone?data:data.slice(0,10);
 const selected=data.find(row=>row.key===rankSelectedPlayerKey);
 return `<div class="gr-overall-body">
  <div class="gr-score-summary"><div class="gr-summary-item"><span class="gr-summary-icon" aria-hidden="true">♟</span><span><strong>${data.length}</strong><small>JOKALARI</small></span></div><div class="gr-summary-item"><span class="gr-summary-icon" aria-hidden="true">✦</span><span><strong>${data.length?rankFmt(data[0].total):'0'}</strong><small>MARKARIK ONENA</small></span></div><div class="gr-summary-item"><span class="gr-summary-icon" aria-hidden="true">⚑</span><span><strong>10</strong><small>JOKO</small></span></div></div>
  ${rankingPodium(data)}
  ${selected?rankingPlayerDetail(selected):''}
  <section class="gr-leader-section" aria-label="Jokalarien sailkapena">
   <div class="gr-section-heading"><div><span class="gr-section-overline">JOKALARI GUZTIAK</span><h3>✦ Sailkapen nagusia</h3></div><span class="gr-section-side">Gehienez 10.000 puntu</span></div>
   ${data.length?`<div class="gr-table-wrap"><table class="gr-table"><thead><tr><th scope="col">#</th><th scope="col">Jokalaria</th><th scope="col">Jokoak</th><th scope="col">Puntuak</th></tr></thead><tbody>
   ${limited.map((player,i)=>`<tr class="${i<3?'gr-top gr-rank-'+(i+1):''}"><td class="gr-place"><span class="gr-row-medal">${rankMedal(i)}</span></td><td><button type="button" class="gr-player-button" data-rank-player="${esc(player.key)}" aria-label="${esc(player.name)}, ${rankFmt(player.total)} puntu, xehetasunak ikusi"><span class="gr-row-avatar" aria-hidden="true">${rankAvatar(player.name)}</span><span class="gr-row-person"><strong>${esc(player.name)}</strong><span class="gr-row-track" aria-hidden="true"><i style="width:${rankPercent(player.total)}%"></i></span></span><span class="gr-detail-indicator" aria-hidden="true">›</span></button></td><td class="gr-completed"><span>${player.complete}</span><small> / 10</small></td><td class="gr-points">${rankFmt(player.total)}</td></tr>`).join('')}
   </tbody></table></div>${data.length>10?`<button type="button" class="gr-show-all" data-rank-toggle="all">${rankShowEveryone?'Lehen 10ak ikusi':`Jokalari guztiak ikusi (${data.length})`} <span aria-hidden="true">⌄</span></button>`:''}`:
   `<div class="gr-empty"><span class="gr-empty-symbol" aria-hidden="true">🏆</span><strong>Podioa zuen zain dago!</strong><p>Oraindik ez dago gordetako puntuaziorik. Amaitu joko bat eta hemen agertuko da zure markarik onena.</p></div>`}
  </section>
 </div>`;
}
function perGameRankingMarkup(){
 return `<section class="gr-game-view"><div class="gr-section-heading"><div><span class="gr-section-overline">JOKO BAKOITZEKO MARKAK</span><h3>✦ Jokoz jokoko TOP 10</h3></div><span class="gr-section-side">10 sailkapen</span></div>
  <div class="gr-games-grid">${GAME_LIST.map(g=>{
   const records=leaders(g.id);
   return `<section class="gr-game-ranks"><div class="gr-game-title"><span class="gr-game-number">${g.number}</span><h4>${esc(g.name)}</h4><span class="gr-game-trophy" aria-hidden="true">🏅</span></div>
    ${records.length?`<ol>${records.map((x,i)=>`<li><span class="gr-game-item-rank">${rankMedal(i)}</span><span class="gr-game-item-name">${esc(x.name)}</span><strong>${rankFmt(Number(x.score)||0)}</strong></li>`).join('')}</ol>`:'<p class="gr-no-records">✧ Oraindik ez dago errekorrik.</p>'}</section>`;
  }).join('')}</div></section>`;
}
function renderRankingInfo(){
 $('info-title').textContent='Sailkapenak';
 $('info-content').innerHTML=`<div class="gr-ranking-ui">
  <div class="gr-hero"><div class="gr-hero-emblem" aria-hidden="true">🏆</div><div class="gr-hero-content"><span class="gr-hero-kicker">ISLAMAREN ABENTURA · 10 JOKO</span><h3>Sailkapen Orokorra</h3><p>Hamar abentura. Txapeldun bakarra.</p></div><span class="gr-hero-spark gr-hero-spark-left" aria-hidden="true">✧</span><span class="gr-hero-spark gr-hero-spark-right" aria-hidden="true">✧</span></div>
  <div class="gr-tabs" role="group" aria-label="Sailkapen mota"><button type="button" data-rank-view="overall" aria-pressed="${rankActiveView==='overall'}" class="${rankActiveView==='overall'?'gr-selected':''}">🏆 Orokorra <span>· 10 joko</span></button><button type="button" data-rank-view="games" aria-pressed="${rankActiveView==='games'}" class="${rankActiveView==='games'?'gr-selected':''}">★ Jokoz jokoko TOP 10</button></div>
  <div class="gr-panel">${rankActiveView==='overall'?overallRankingMarkup():perGameRankingMarkup()}</div>
  <div class="gr-local-note"><span class="gr-local-note-icon" aria-hidden="true">ⓘ</span><p><strong>Tokiko sailkapena:</strong> ordenagailu eta nabigatzaile honetako markak bakarrik agertzen dira. Erabili beti <strong>goitizen bera</strong> hamar jokoetan; ikaskideen zuzeneko markak ez daude oraindik konektatuta.</p></div>
 </div>`;
}
function showInfo(rankingMode=false){
 $('info-modal').classList.remove('hidden');
 $('info-modal').querySelector('.info-modal').classList.toggle('gr-ranking-modal',rankingMode);
 if(rankingMode){rankActiveView='overall';rankShowEveryone=false;rankSelectedPlayerKey=null;renderRankingInfo();}
 else{
  $('info-title').textContent='Nola jokatu?';
  $('info-content').innerHTML='<p><strong>10 joko interaktibo</strong> daude. Joko bakoitzak bere jarraibideak, denbora eta bizitzak ditu: irakurri hasi aurretik.</p><p>Hautatu txartel bat eta gero helburua; joko batzuetan arrastatu ere egin daiteke. Mugikorrean, sakatu eta kokatu. Irudi zabalak alde batera mugi ditzakezu.</p><p><strong>Egiaztatu:</strong> lotura-jokoetan hutsune guztiak bete behar dira egiaztatzeko. Osatu gabe daudenean abisua agertzen da, bizitzarik kendu gabe.</p><p><strong>Puntuazioa:</strong> joko bakoitzean 1.000 puntu lortu daitezke, baina kalkulua ez da berdina. Erronka guztiak osatzen dituzten partidak gordetzen dira errekorretan; amaitu gabe geratzen direnek emaitza partziala erakusten dute. 9. jokoak bi erronka dauzka; 10. jokoak bakarra.</p><p><strong>SAILKAPENAK:</strong> TOP 10 joko bakoitzeko eta Sailkapen Orokorra daude. Sailkapen Orokorrak jokalari bakoitzaren hamar jokoetako markarik onenak gehitzen ditu (10.000 puntu gehienez), eta jokatu gabeko jokoek zero balio dute. Puntuazioak ordenagailu eta nabigatzaile honetan bakarrik gordetzen dira; ikaskideen markak ez dira zuzenean partekatzen. Erabili goitizen bera hamar jokoetan eta goitizen desberdina ikasle bakoitzeko, ez benetako izen-abizenik.</p>';
 }
}
function closeInfo(){$('info-modal').classList.add('hidden')}
function wire(){setupGallery();$('start-hero').addEventListener('click',()=>document.getElementById('game-gallery').scrollIntoView({behavior:'smooth',block:'start'}));$('home-ranking').addEventListener('click',()=>showInfo(true));$('home-help').addEventListener('click',()=>showInfo(false));$('info-content').addEventListener('click',event=>{const view=event.target.closest('[data-rank-view]');if(view){rankActiveView=view.dataset.rankView;rankShowEveryone=false;rankSelectedPlayerKey=null;renderRankingInfo();return}const player=event.target.closest('[data-rank-player]');if(player){rankSelectedPlayerKey=player.dataset.rankPlayer;renderRankingInfo();$('info-content').querySelector('.gr-selected-player')?.focus();return}const clear=event.target.closest('[data-rank-clear]');if(clear){rankSelectedPlayerKey=null;renderRankingInfo();return}const all=event.target.closest('[data-rank-toggle]');if(all){rankShowEveryone=!rankShowEveryone;renderRankingInfo();}});window.addEventListener('storage',event=>{if(event.key===localKey&&!$('info-modal').classList.contains('hidden')&&$('info-content').querySelector('.gr-tabs'))renderRankingInfo()});$('info-close').addEventListener('click',closeInfo);$('info-ok').addEventListener('click',closeInfo);$('back-home').addEventListener('click',viewHome);$('modal-close').addEventListener('click',closeStart);$('modal-play').addEventListener('click',startGame);$('player-name').addEventListener('keydown',e=>{if(e.key==='Enter')startGame()});$('check-button').addEventListener('click',submitPlacement);$('reset-button').addEventListener('click',()=>{if(state.finished)return;const keep=new Set(state.placementLocked||[]);for(const [cat,cards] of Object.entries(state.assignments)){if(Array.isArray(cards))state.assignments[cat]=cards.filter(id=>keep.has(id));}state.chosen=null;state.step=keep.size;$('feedback').textContent='Txartelak berriro antolatu ditzakezu.';renderPlacement()});$('replay-game').addEventListener('click',()=>{$('result-modal').classList.add('hidden');startGame()});$('result-home').addEventListener('click',viewHome);$('sound-toggle').addEventListener('click',()=>{state.sound=!state.sound;$('sound-toggle').textContent=state.sound?'♫':'♪';$('sound-toggle').setAttribute('aria-label',state.sound?'Soinua itzali':'Soinua piztu')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeStart();closeInfo()}})}
wire();
(async()=>{if(location.protocol!=='https:'&&location.protocol!=='http:')return;try{const r=await fetch('/api/status',{cache:'no-store'}),d=await r.json();if(r.ok&&d.online){state.online=true;$('home-mode').textContent='ONLINE · TOP 10 PARTEKATUA';$('rank-disclaimer').textContent='Sailkapen partekatua · 10 segundoro';setInterval(()=>{if(state.game)ranking()},10000)}}catch{}})();
